      az: "Beyincik hərəkəti əmr etmir, dəqiqləşdirir — ona görə zədə gücü saxlayaraq ataksiya, dismetriya və məqsədli tremor verir. İflic cəlbedici cavabdır, lakin o, kortikospinal zədə tələb edir. Həmçinin beyincik əlamətləri eyni tərəflidir, motor qabıq insultunun əks tərəfli əlamətlərindən fərqli olaraq.",
