      az: "Üzün yuxarı hissəsinin motor neyronları hər iki motor qabıqdan giriş alır, ona görə birtərəfli mərkəzi motor neyron zədəsində alın işləməkdə qalır; üz sinirinin özünün zədəsi isə bu birləşmədən sonradır və həmin tərəfdə hər şeyi iflic edir. Sinirin alına çatmadığını demək Bell iflicinin məhz həmin qırışları hamarladığını xatırlayana qədər cəlbedicidir.",
