        az: "Dırmaşan liflər aşağı zeytundan gəlir və hər biri bir Purkinye hüceyrəsini sarıyır; yosunabənzər liflər digər mənbələrdən gəlir və Purkinye hüceyrələrinə dənəvər hüceyrələr vasitəsilə çatır",
