      en: "Crystals sitting on a gel over the hair cells lag behind when you accelerate or tip your head, bending the hairs and reporting straight-line motion and head tilt — which is why you feel a lift start to rise even with your eyes closed. Sound frequency is tempting because these organs share the inner ear with the cochlea, but they have no tonotopic arrangement at all.",
      az: "Tük hüceyrələrinin üstündəki geldə oturan kristallar siz sürətləndikdə və ya başınızı əydikdə geri qalır, tükləri bükür və düzxətli hərəkəti ilə başın əyilməsini bildirir — buna görə gözünüz qapalı olsa da liftin qalxmağa başladığını duyursunuz. Səs tezliyi cəlbedicidir, çünki bu orqanlar daxili qulağı salyangozla bölüşür, lakin onlarda heç bir tonotopik quruluş yoxdur.",
