      az: "Foveada konusvari hüceyrələrin sıxlığı ən yüksəkdir və bağlantı bir konusa bir qanqlion hüceyrəsi nisbətinə yaxınlaşır, ona görə incə məkan detalı qabığa qədər qorunur; qabıqda fovea təmsili həm də çox böyüdülmüşdür. Çöpcüklərin orada ən sıx olması cəlbedici tərsinə çevirmədir — məhz mərkəzdə çöpcük yoxdur, buna görə tutqun ulduza düz baxanda o itir.",
