      az: "Nosiseptorlar iki tipli sərbəst sinir uclarıdır; mielinli A-delta lifləri çılpaq C liflərindən bir neçə dəfə sürətli keçirir, ona görə kəskin xəbərdarlıq eyni zədədən gələn yandırıcı ağrıdan xeyli əvvəl çatır. Beyində ikiqat emal cəlbedicidir, lakin gecikmə periferik sinirin özündə ölçülə bilir.",
