      az: "Nasos natriumu xaricdə, kaliumu daxildə cəmləşdirir — bu, aksiyon potensialı zamanı natriuma içəriyə doğru hərəkət qüvvəsi verir və sükunət potensialını kalium tarazlığına yaxın saxlayır. Bu ikisini yerdəyişmək cəlbedici səhvdir və aksiyon potensialını tərsinə çevirərdi: natrium kanalları açılanda hüceyrə hiperpolyarizasiya olardı.",
