      az: "Monoaminlər xüsusi geri udma daşıyıcıları ilə təkrar istifadəyə qaytarılır — SSRİ məhz bunu bloklayır ki, serotonin daha uzun müddət təsir göstərsin. Yarıqda fermentlə parçalanma cəlbedicidir, çünki sinir-əzələ birləşməsində asetilxolinesteraza belə işləyir, lakin monoamin sistemləri məhv etmə yerinə geri qaytarma üzərində qurulub.",
