      az: "Qlisin onurğa interneyronlarında və motor neyronlarında xlor kanallarını açır; onu strixninlə bloklamaq və ya tetanus toksininin etdiyi kimi itirmək güclü əzələ spazmları verir, çünki motor neyronları heç nə cilovlamır. Asetilxolin cəlbedicidir, çünki bir addım aşağıda, sinir-əzələ birləşməsindəki transmitterdir, lakin orada o oyadıcıdır.",
