      az: "Hər dalğa yarığa boşalan bir vezikuldur; veziküllər təxminən bərabər miqdar daşıdığı üçün dalğalar eyni ölçüdədir — bu müşahidə transmitter ifrazının kvant xarakterli olduğunu, çağırılmış cavabın isə bu vahidin qatı olduğunu təsdiqlədi. Avadanlıq küyü cəlbedicidir, lakin küy sabit ölçüdə gəlməzdi və ifraz bloklandıqda yox olmazdı.",
