      az: "Avtoreseptorlar ifraz edən terminalın özündə yerləşir və ona mənfi geri əlaqə verir, ona görə çox ifraz etmiş terminal növbəti dəfə daha az buraxır — bu reseptorlara təsir edən dərmanların bağlandığı yerə görə ötürülməni ya artırıb, ya azaltmasının səbəblərindən biri budur. Siqnalı irəli aparmaq cəlbedicidir, lakin bu, yarığın digər tərəfindəki postsinaptik reseptorun işidir.",
