      az: "Təsir transmitterə deyil, reseptora aiddir: nikotinik reseptorlar əzələ lifini birbaşa depolyarizə edən kanallardır, ürəyin muskarin reseptorları isə G zülalı vasitəsilə kalium kanallarını açır və ritm ötürücüsünü yavaşıdır. Fərqli miqdarda ifraz cəlbedicidir, lakin heç bir doza nikotinik reseptoru muskarin reseptoru kimi davranmağa məcbur etmir.",
