      az: "Motor neyronlar ölçü sırası ilə işə salınır, ona görə incə, az qüvvəli nəzarəti yorulmağa davamlı kiçik vahidlər verir, güclü vahidlər isə yalnız lazım olanda qoşulur — buna görə zərif tutuş sabit, maksimal qaldırma isə titrəyicidir. Aksiyon potensiallarının böyüməsi cəlbedicidir, lakin impulslar «ya var, ya yox» prinsipi ilə işləyir və qüvvəni amplituda ilə kodlaya bilməz.",
