    topic: "function",
    sub: "memory",
    tier: 3,
    difficulty: 3,
    q: {
      en: "Knowing that Baku is on the Caspian, versus remembering your own first trip there. What is the distinction?",
      az: "Bakının Xəzər sahilində olduğunu bilmək və ora ilk səfərinizi xatırlamaq. Fərq nədir?",
    },
    choices: [
      { en: "Procedural versus working memory", az: "Prosedur və işlək yaddaş" },
      { en: "There is no meaningful distinction", az: "Mənalı fərq yoxdur" },
      { en: "Short-term versus long-term memory", az: "Qısamüddətli və uzunmüddətli yaddaş" },
      { en: "Semantic versus episodic memory", az: "Semantik və epizodik yaddaş" },
    ],
    answer: 3,
    why: {
      en: "Semantic memory is knowledge stripped of its context, while episodic memory keeps the where and when of a personal event, and the two can dissociate — patients may keep a rich store of facts while losing all recollection of living through them. Short versus long term is tempting, but both of these are long-term stores.",
      az: "Semantik yaddaş kontekstindən ayrılmış biliklərdir, epizodik yaddaş isə şəxsi hadisənin yerini və vaxtını saxlayır; bu ikisi ayrıla bilir — xəstələr zəngin fakt ehtiyatını saxlayıb onları yaşadıqlarına dair bütün xatirələri itirə bilər. Qısa və uzunmüddətli bölgü cəlbedicidir, lakin bunların hər ikisi uzunmüddətli anbardır.",
    },
    see: { href: "limbic/index.html", en: "See the limbic system in 3D →", az: "Limbik sistemi 3D-də gör →" },
