      az: "Yuxu təxminən doxsan dəqiqəlik dövrlərlə gedir və dövrlərin tərkibi gecə boyu dəyişir: yavaş dalğalı yuxu əvvələ, REM-in çoxu isə son saatlara düşür — buna görə yuxunu qısaltmaq qeyri-mütənasib şəkildə çox REM itkisi verir. Sonda tək uzun REM bloku cəlbedicidir, çünki REM gecikən saatlarda daha ağırdır, lakin o bir yerdə deyil, bir neçə ayrı epizodla gəlir.",
