      az: "Kobud talamik qısayol qabıq obyekti müəyyən etməyi bitirməmiş amiqdalaya çatır, ona görə bədən təxmini uyğunluğa reaksiya verir, qabıq yolu isə bir an sonra gəlib onu təsdiqləyir və ya ləğv edir — gecikmənin qiyməti yüksək olduğu yerdə dəqiqliyi sürətə dəyişən quruluş. Şüurlu tanımanın əvvəl gəldiyini israr etmək cəlbedicidir, lakin diksinmə onu açıq şəkildə qabaqlayır.",
