    answer: 0,
    why: {
      en: "Discrimination depends on whether the two stimuli excite different sets of afferents, and on the back one receptor's field can be several centimetres wide, so both points land inside it and report as one. Thicker skin is tempting, but the palm is thick-skinned and still highly discriminating — density and field size are what matter.",
      az: "Ayırd etmə iki stimulun fərqli afferent dəstələrini oyadıb-oyatmamasından asılıdır; kürəkdə bir reseptorun sahəsi bir neçə santimetr ola bilir, ona görə hər iki nöqtə onun içinə düşür və bir kimi bildirilir. Qalın dəri cəlbedicidir, lakin ovucun dərisi qalın olsa da yüksək ayırd etmə qabiliyyəti saxlayır — həlledici olan sıxlıq və sahə ölçüsüdür.",
    },
