      az: "Hər arxa kök dərinin müəyyən zolağını innervasiya edir; bir hissi qanqlionda oyanan kəmərləyici dəmrov məhz belə zolaq verir — buna görə səpki orta xəttə bu qədər dəqiq riayət edir. Qan damarı paylanması cəlbedicidir, lakin damar hövzələri səliqəli üfüqi zolaqlarla getmir və orta xəttdə dayanmır.",
