      az: "Cərəyan aktiv sahədən hər iki tərəfə yayılır, lakin arxada qalan nahiyənin natrium kanalları inaktivdir, ona görə yalnız qarşıdaki membran həddə çata bilir və impuls bir istiqamətə bağlanır. Arxada kanalın olmaması cəlbedicidir, lakin onlar tam mövcuddur — ortadan stimullaşdırılan akson eyni anda hər iki istiqamətə impuls verir.",
