      az: "Mikroqliya inkişafın erkən mərhələsində qan mənşəyindən gəlir və sonra beyində yaşayır: nazik çıxıntıları ilə fasiləsiz nəzarət edir, zibilləri, ölü hüceyrələri və lazımsız sinapsları udur. Astrosit cəlbedicidir, çünki o da zədəyə cavab verir və qliya çapığı yaradır, lakin mikroqliya kimi faqositoz etmir.",
