    answer: 3,
    why: {
      en: "In classical conditioning the animal learns a relationship between two events it cannot control, while in operant conditioning the animal learns that its own behaviour produces an outcome, and the behaviour is shaped by that consequence. Saying there is no difference is tempting because both involve association, but only one puts the animal's action in the loop.",
      az: "Klassik şərtləndirmədə heyvan idarə edə bilmədiyi iki hadisə arasındaki əlaqəni öyrənir; operant şərtləndirmədə isə öz davranışının nəticə verdiyini öyrənir və davranış həmin nəticə ilə formalaşır. Fərq olmadığını demək cəlbedicidir, çünki hər ikisində assosiasiya var, lakin yalnız birində heyvanın hərəkəti dövrənin içindədir.",
    },
